def predict(board, action):
    row, col = action
    action_char = 'MOUSE'
    new_board = [list(row) for row in board]

    if action_char == 'MOUSE':
        for i in range(max(0, col-2), min(64, col+3)):
            for j in range(max(0, row-2), min(64, row+3)):
                if new_board[j][i] != ' ':
                    new_board[j][i] = 'S'
                elif new_board[j][i] == ' ':
                    if (j, i) == (row, col):
                        new_board[j][i] = 'p'
                    else:
                        new_board[j][i] = 'N'

    return [''.join(row) for row in new_board]
